using EZapi;
using System.Text.Json;
var checks=new List<string>();
void Check(bool value,string name){if(!value)throw new Exception(name);checks.Add(name);}
void Reject(Action action,string name){try{action();}catch(ArgumentException){checks.Add(name);return;}catch(InvalidOperationException){checks.Add(name);return;}throw new Exception("Expected rejection: "+name);}
// Exercise full severity ordering, instance independence, native dispatch and lazy execution.
foreach(var configured in Enum.GetValues<LogLevel>())foreach(var message in Enum.GetValues<LogLevel>())
    Check(LogLevels.Allows(configured,message)==(configured!=LogLevel.Off&&message!=LogLevel.Off&&message>=configured),$"threshold {configured}/{message}");
foreach(var pair in new[]{(" DEBUG ",LogLevel.Debug),("info",LogLevel.Info),("Warning",LogLevel.Warn),("ERROR",LogLevel.Error),("off",LogLevel.Off),("调试",LogLevel.Debug),("信息",LogLevel.Info),("警告",LogLevel.Warn),("错误",LogLevel.Error),("关闭",LogLevel.Off)})
    Check(LogLevels.TryParse(pair.Item1,out var parsed)&&parsed==pair.Item2,"parse "+pair.Item1);
foreach(var text in new string?[]{null,""," ","verbose","1","info\nerror"})Check(!LogLevels.TryParse(text,out var parsed)&&parsed==LogLevel.Info,"invalid level "+text);
Reject(()=>LogLevels.Allows((LogLevel)99,LogLevel.Info),"invalid configured enum");Reject(()=>LogLevels.Allows(LogLevel.Info,(LogLevel)(-1)),"invalid message enum");
var entries=new List<LogEntry>();var log=new ModLog("author.tools",LogLevel.Debug,entries.Add);log.Debug("d");log.Info("i");log.Warn("w");log.Error("e");log.Callback("c");
Check(entries.Select(x=>x.Level).SequenceEqual(new[]{LogLevel.Debug,LogLevel.Info,LogLevel.Warn,LogLevel.Error,LogLevel.Debug}),"all methods preserve severity");
Check(entries[4].IsCallback&&entries[4].Formatted=="[author.tools] [callback] c"&&log.IsDebugEnabled,"callback remains structured debug message");
var quiet=new ModLog("other.mod",LogLevel.Error,entries.Add);quiet.Info("hidden");quiet.Error("shown");Check(entries.Count==6&&entries[^1].OwnerId=="other.mod"&&log.Level==LogLevel.Debug,"independent mod thresholds and owner");
int evaluations=0;quiet.Write(LogLevel.Debug,()=>{evaluations++;return "expensive";});quiet.Write(LogLevel.Error,()=>{evaluations++;return "needed";});Check(evaluations==1&&entries[^1].Message=="needed","lazy formatter only for enabled level");
new ModLog("off.mod",LogLevel.Off,entries.Add).Error("hidden");Check(entries.Count==7,"off suppresses every severity");
var native=new ModLog("native.mod",LogLevel.Debug);native.Debug("d");native.Info("i");native.Warn("w");native.Error("e");Check(MelonLoader.MelonLogger.Entries.Select(x=>x.Level).SequenceEqual(new[]{"Info","Info","Warn","Error"}),"native sink routes real backend facade methods");
Reject(()=>new ModLog("bad owner"),"bad owner");Reject(()=>new ModLog("a",(LogLevel)98),"invalid logger level");Reject(()=>log.Info(null!),"null message");Reject(()=>log.Write(LogLevel.Info,(Func<string>)null!),"null lazy message");
Reject(()=>new ModLog("fail",sink:_=>throw new InvalidOperationException("sink")).Info("x"),"custom sink failure is observable");
// Model actual event traces: releases, outside origin, repeated close, independent windows.
var capture=new WindowInputCapture();Check(!capture.BlocksPointer(0,false,false),"closed initial pointer free");capture.Open(1,true);Check(capture.BlocksPointer(1,false,true),"opening held click captured outside");Check(capture.BlocksPointer(2,false,true),"opening gesture survives outside");Check(capture.BlocksPointer(3,false,false)&&capture.BlocksPointer(3,false,false),"release frame remains blocked on repeated query");Check(!capture.BlocksPointer(4,false,false)&&capture.BlocksPointer(4,true,false),"hover only inside open panel");
Check(capture.BlocksPointer(5,true,true)&&capture.BlocksPointer(6,false,true),"inside press captures drag outside");capture.Close(7,true);Check(!capture.IsOpen&&capture.BlocksPointer(8,false,true),"close during gesture retains capture");Check(capture.BlocksPointer(9,false,false)&&!capture.BlocksPointer(10,false,false),"closed gesture release barrier expires following frame");capture.Close(11,true);Check(!capture.BlocksPointer(11,false,true),"repeated close on closed panel creates no new gesture");
capture.Reset();capture.Open(0,false);capture.BlocksPointer(1,false,true);Check(capture.BlocksPointer(2,true,true)&&!capture.BlocksPointer(3,false,true),"outside-origin drag not permanently stolen by hover");capture.Close(4,false);Check(capture.BlocksPointer(4,false,false)&&!capture.BlocksPointer(5,false,false),"close frame suppressed without held button");
var other=new WindowInputCapture();other.Open(5,false);Check(!capture.IsOpen&&other.IsOpen&&!capture.BlocksPointer(6,false,false),"window instances isolated");capture.Reset();Check(!capture.BlocksPointer(0,false,false),"reset allows new frame timeline");Reject(()=>capture.Open(-1,false),"negative frame rejected");capture.BlocksPointer(4,false,false);Reject(()=>capture.Close(3,false),"backward frame requires reset");Check(!capture.IsOpen&&!capture.BlocksPointer(4,false,false),"invalid transition leaves state unchanged");
// Normalize explicit aliases only; no vendor IDs or save objects are touched.
var terminal=ManufacturingTerminal.ItemId;Check(ManufacturingTerminal.NormalizeItemId("  "+terminal+"  ")==terminal,"canonical trim");Check(ManufacturingTerminal.NormalizeItemId("other.mod.item")=="other.mod.item","foreign ID preserved");Check(ManufacturingTerminal.NormalizeItemId("old.author.press",new[]{"old.author.press"})==terminal,"explicit legacy alias remaps");Check(ManufacturingTerminal.NormalizeItemId("OLD.author.press",new[]{"old.author.press"})=="OLD.author.press","aliases ordinal case-sensitive");
foreach(var id in new string?[]{null,""," ","a b","a\nb",new string('x',161)})Reject(()=>ManufacturingTerminal.NormalizeItemId(id!),"invalid terminal ID "+id?.Length);
Reject(()=>ManufacturingTerminal.NormalizeItemId(terminal,new[]{"old"," old "}),"duplicate normalized alias");Reject(()=>ManufacturingTerminal.NormalizeItemId(terminal,new[]{"bad id"}),"validate all aliases even on canonical input");Reject(()=>ManufacturingTerminal.NormalizeItemId(terminal,Enumerable.Range(0,65).Select(i=>"old"+i).ToArray()),"bounded alias list");
var report=new{passed=checks.Count,failed=0,cases=checks,nativeRuntimeVerified=false,scope="Real logging/filtering, pointer event state and terminal ID normalization; MelonLoader sink is an instrumented boundary; no global input patch, game window or native terminal mutation"};
File.WriteAllText("work/ezapi-public-helper-tests.json",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{report.passed,report.failed,report.scope}));
